package com.circlenet.domain.trust;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="emergency_access_events") public class EmergencyAccessEventEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="request_id",nullable=false) private Long requestId;@Column(name="actor_user_id",nullable=false) private Long actorUserId;@Column(nullable=false,length=40) private String action;@Column(name="resource_id") private Long resourceId;@Column(name="occurred_at",nullable=false) private Instant occurredAt=Instant.now();public void setRequestId(Long v){requestId=v;}public void setActorUserId(Long v){actorUserId=v;}public void setAction(String v){action=v;}public void setResourceId(Long v){resourceId=v;}}
